function focusMarkup(){return `<div class="focus-backdrop" id="focusBackdrop"></div><header class="focus-top"><button class="focus-back" id="closeFocus" aria-label="Закрыть плеер">${playerIcon('down')}<span>К музыке</span></button><div class="focus-wordmark">soulroom<span>СЕЙЧАС ИГРАЕТ</span></div><div class="focus-window-actions"><span class="focus-source-badge" id="focusSource"></span><button id="nativeFullscreen" class="icon-button" aria-label="На весь экран" title="На весь экран">${playerIcon('expand')}</button></div></header><div class="focus-body"><section class="focus-song"><div class="focus-art-frame"><div class="focus-cover" id="focusCover"></div></div><div class="focus-meta"><div><h1 id="focusTitle"></h1><p id="focusArtist"></p></div><button data-focus-control="like" class="focus-heart icon-button" aria-label="В любимое">${playerIcon('heart')}</button></div><div class="focus-album-note"><span>ТВОЁ ЛИЧНОЕ ПРОСТРАНСТВО</span><span>♪</span></div></section><section class="focus-content"><div class="focus-content-header"><div class="focus-tabs"><button data-focus-tab="lyrics" class="selected">${playerIcon('lyrics')}<span>Текст</span></button><button data-focus-tab="clips">${playerIcon('video')}<span>Клип</span></button></div><details class="focus-options"><summary aria-label="Настроить синхронизацию" title="Настроить синхронизацию">${playerIcon('sliders')}</summary><div class="focus-options-panel"><strong>Синхронизация</strong><label>Сдвиг текста, сек.<input type="number" id="lyricsOffset" min="-60" max="60" step=".5" value="0"></label><label>Сдвиг клипа, сек.<input type="number" id="videoOffset" min="-120" max="120" step=".5" value="0"></label><button id="retryLyrics">Найти текст снова</button><button id="importLrc">Открыть LRC-файл</button><input type="file" id="lrcFile" accept=".lrc,text/plain" hidden></div></details></div><div id="focusText"><div class="focus-empty"><div class="sound-mark">${soundDrawing()}</div><span class="eyebrow">МОМЕНТ ДЛЯ СЕБЯ</span><h2>Слушай.<br><em>Оставайся в музыке.</em></h2><p id="lyricsStatus" role="status"></p><div class="focus-next"><div class="focus-next-heading"><span>ДАЛЬШЕ В ТВОЕЙ КОМНАТЕ</span><span>↗</span></div><div id="focusNext"></div></div></div><div id="lyricsInfo" role="status"></div><div id="lyricsLines" class="lyrics-lines"></div></div><div id="focusClips" class="hidden"><div class="video-stage"><div id="youtubeMount"></div><div class="video-placeholder" id="videoPlaceholder">${playerIcon('video')}<strong>У музыки есть история.</strong><span>Подберём подходящее видео автоматически</span></div></div><div class="clip-caption"><span>ВИДЕО К ЭТОЙ ПЕСНЕ</span><a id="externalClip" target="_blank" rel="noopener">Открыть источник ↗</a></div><p id="clipsStatus" role="status"></p><details class="clip-alternatives"><summary>Другая версия видео</summary><div id="clipChoices"></div></details><details class="manual-clip-details"><summary>Открыть клип по ссылке ${playerIcon('plus')}</summary><form id="manualClipForm" class="manual-clip"><input id="clipUrl" type="url" placeholder="Ссылка на YouTube" aria-label="Ссылка на клип YouTube" required><button class="secondary">Открыть</button></form></details><button id="retryClips" class="clip-retry">Обновить подборку</button></div></section></div><footer class="focus-dock"><div class="focus-dock-info"><i class="dot green"></i><span id="focusPlaybackLabel">В твоём ритме</span></div><div class="focus-console"><div class="focus-transport"><button data-focus-control="shuffle" class="icon-button" aria-label="Перемешать">${playerIcon('shuffle')}</button><button data-focus-control="prev" class="icon-button" aria-label="Предыдущий">${playerIcon('previous')}</button><button class="focus-play-button" data-focus-control="play" id="focusPlay" aria-label="Играть или приостановить">${playerIcon('play')}</button><button data-focus-control="next" class="icon-button" aria-label="Следующий">${playerIcon('next')}</button><button data-focus-control="repeat" class="icon-button" aria-label="Повторять">${playerIcon('repeat')}</button></div><div class="timeline"><time id="focusElapsed">0:00</time><input type="range" id="focusSeek" aria-label="Позиция песни" min="0" max="1000" value="0"><time id="focusDuration">0:00</time></div></div><div class="focus-volume"><button class="icon-button" data-open-eq aria-label="Эквалайзер" title="Эквалайзер">${playerIcon('sliders')}</button>${playerIcon('volume')}<input type="range" id="focusVolume" min="0" max="1" step=".01" value="${audio.volume}" aria-label="Громкость песни"></div></footer>`}
function openFocus(){if(!current){toast('Сначала выбери трек.');return}focusOpen=true;focusTab='lyrics';focusPanel.innerHTML=focusMarkup();focusPanel.classList.remove('hidden');document.body.style.overflow='hidden';focusPanel.scrollTop=0;lyricsManualUntil=0;focusTrack=null;updateFocusTrack();$('#closeFocus').focus()}
