function updateFocusTrack(){if(!focusOpen||!current||focusTrack===current.id)return;focusTrack=current.id;destroyVideo();lyricsLines=[];clipItems=[];lyricsOffset=0;videoOffset=0;$('#focusBackdrop').style.backgroundImage=`url("${coverSource(current.cover,image(0))}")`;$('#focusNext').innerHTML=queue.filter(t=>t.id!==current.id).slice(0,2).map(t=>`<button data-focus-next="${esc(t.id)}"><img src="${esc(coverSource(t.cover,image(0)))}" alt=""><span><strong>${esc(t.title)}</strong><small>${esc(artist(t))}</small></span>${playerIcon('play')}</button>`).join('');$('#focusCover').style.backgroundImage=`url("${coverSource(current.cover,image(0))}")`;$('#focusTitle').textContent=current.title;$('#focusArtist').textContent=artist(current);$('#focusSource').textContent=serviceNames[current.source]|| (current.source==='local'?'МОЯ МУЗЫКА':'SOULROOM SESSIONS');$('#lyricsOffset').value=0;$('#videoOffset').value=0;$('#clipChoices').innerHTML='';$('#externalClip').removeAttribute('href');$('#youtubeMount')?.replaceChildren();loadLyrics();if(focusTab==='clips')loadClips();updateFocusTime()}
function renderLyrics(){const node=$('#lyricsLines');if(!node)return;node.scrollTop=0;$('#focusText').dataset.synced=String(lyricsLines.some(l=>Number.isFinite(l.time)));node.innerHTML=lyricsLines.map((line,i)=>`<button class="lyric-line" data-lyric="${i}" ${!Number.isFinite(line.time)?'disabled':''}>${Array.isArray(line.words)&&line.words.length?line.words.map((w,j)=>`<span data-word="${j}">${esc(w.text||w.word||'')}</span>`).join(' '):esc(line.text)}</button>`).join('');updateFocusTime()}
async function loadLyrics(fresh=false){const version=++lyricsVersion;lyricsLines=[];renderLyrics();if(!current)return;const meta=current;$('#lyricsStatus').textContent='Ищем текст и временные метки…';if(!backend||meta.source==='demo'){$('#lyricsStatus').textContent=meta.source==='demo'?'Инструментальная сессия. Можно открыть свой LRC-файл.':'Поиск текста доступен в локальном приложении. Можно открыть свой LRC-файл.';return}try{const params=new URLSearchParams({title:meta.title,artist:artist(meta),duration:String(meta.duration||audio.duration||0),album:meta.album||'',fresh:fresh?'1':'0'});const data=await api(`lyrics/${encodeURIComponent(meta.source)}/${encodeURIComponent(meta.sourceId||meta.id)}?${params}`);if(!focusOpen||version!==lyricsVersion||current.id!==meta.id)return;lyricsLines=Array.isArray(data.synced)&&data.synced.length?data.synced.filter(l=>Number.isFinite(l.time)&&typeof l.text==='string').sort((a,b)=>a.time-b.time):String(data.plain||'').split('\n').filter(Boolean).map(text=>({text,time:null}));$('#focusText').dataset.synced=String(lyricsLines.some(l=>Number.isFinite(l.time)));$('#lyricsStatus').textContent=lyricsLines.length?(Number.isFinite(lyricsLines[0].time)?'Синхронизированный текст · нажми на строку для перехода':'Текст без временных меток — синхронизация недоступна'):(data.instrumental?'Инструментальный трек.':'Текст не найден. Попробуй снова или открой LRC.');renderLyrics()}catch(e){if(focusOpen&&version===lyricsVersion)$('#lyricsStatus').textContent='Текст не загрузился. Попробуй снова или открой LRC.'}}
function parseLocalLrc(text){const lines=[];for(const line of text.split(/\r?\n/)){const stamps=[...line.matchAll(/\[(\d+):(\d+(?:\.\d+)?)\]/g)];const value=line.replace(/\[[^\]]*\]/g,'').trim();if(value)for(const stamp of stamps)lines.push({time:Number(stamp[1])*60+Number(stamp[2]),text:value})}return lines.sort((a,b)=>a.time-b.time)}
