function centerLyric(node,instant=false){const container=$('#lyricsLines');if(!container||!node)return;const box=container.getBoundingClientRect(),line=node.getBoundingClientRect();const top=container.scrollTop+line.top-box.top-(container.clientHeight-line.height)/2;container.scrollTo({top:Math.max(0,top),behavior:instant||!appearance.motion?'instant':'smooth'})}
