function updateFocusTime(){focusPanel.classList.toggle('is-playing',!audio.paused&&!audio.ended);if(!focusOpen)return;updateFocusTrack();$('#focusPlay').innerHTML=playerIcon(audio.paused?'play':'pause');$('#focusPlaybackLabel').textContent=audio.paused?'Музыка на паузе':'Сейчас звучит';document.querySelectorAll('[data-focus-control=like]').forEach(n=>n.classList.toggle('is-on',likes.has(current?.id)));document.querySelectorAll('[data-focus-control=shuffle]').forEach(n=>n.classList.toggle('is-on',shuffle));document.querySelectorAll('[data-focus-control=repeat]').forEach(n=>n.classList.toggle('is-on',repeat));$('#focusElapsed').textContent=fmt(audio.currentTime);$('#focusDuration').textContent=fmt(audio.duration);$('#focusSeek').value=Number.isFinite(audio.duration)?audio.currentTime/audio.duration*1000:0;const now=audio.currentTime+lyricsOffset;let active=-1;lyricsLines.forEach((l,i)=>{if(Number.isFinite(l.time)&&l.time<=now)active=i});document.querySelectorAll('.lyric-line').forEach((node,i)=>{const changed=!node.classList.contains('current')&&i===active;node.classList.toggle('current',i===active);if(changed&&focusTab==='lyrics'&&Date.now()>lyricsManualUntil)centerLyric(node);const words=lyricsLines[i]?.words;node.querySelectorAll('[data-word]').forEach((span,j)=>span.classList.toggle('sung',!!words&&Number.isFinite(words[j]?.start)&&now>=words[j].start))});syncVideo()}
let youtubePromise;function loadYoutube(){if(window.YT?.Player)return Promise.resolve();if(youtubePromise)return youtubePromise;youtubePromise=new Promise((resolve,reject)=>{const script=document.createElement('script');script.src='https://www.youtube.com/iframe_api';script.onerror=()=>{youtubePromise=null;reject(Error('YouTube недоступен'))};window.onYouTubeIframeAPIReady=resolve;document.head.append(script);setTimeout(()=>{if(!window.YT?.Player){youtubePromise=null;reject(Error('YouTube не ответил'))}},12000)});return youtubePromise}
async function loadClips(){const version=++clipVersion;destroyVideo();$('#videoPlaceholder')?.classList.remove('hidden');$('#clipsStatus').textContent='Ищем клипы к этому треку…';if(!backend||current.source==='demo'){$('#clipsStatus').textContent=current.source==='demo'?'У встроенной сессии нет клипа.':'Поиск клипов доступен в локальном приложении.';return}try{const d=await api('clips?'+new URLSearchParams({title:current.title,artist:artist(current),duration:String(current.duration||audio.duration||0)}));if(!focusOpen||version!==clipVersion)return;clipItems=(d.items||[]).filter(v=>v.provider==='peertube'&&/^https:\/\//.test(v.embedUrl||'')||/^[a-zA-Z0-9_-]{11}$/.test(v.id));$('#clipsStatus').textContent=clipItems.length?'Нашли подходящее видео. Открываем автоматически…':'Клип не найден. Попробуй снова.';$('#clipChoices').innerHTML=clipItems.slice(0,5).map((v,i)=>`<button class="secondary" data-clip="${i}">${esc(v.title)}</button>`).join('');if(clipItems.length)selectClip(0)}catch(e){if(focusOpen&&version===clipVersion)$('#clipsStatus').textContent='Клипы не загрузились. Проверь соединение и попробуй снова.'}}
async function selectClip(i){const clip=clipItems[i];if(!clip)return;activeClipIndex=i;destroyVideo();$('#videoPlaceholder')?.classList.add('hidden');const version=clipVersion;$('#externalClip').href='https://www.youtube.com/watch?v='+clip.id;$('#clipsStatus').textContent='Открываем видео…';try{await loadYoutube();if(!focusOpen||version!==clipVersion||focusTab!=='clips')return;$('#youtubeMount')?.remove();const mount=document.createElement('div');mount.id='youtubeMount';$('.video-stage').prepend(mount);videoPlayer=new YT.Player('youtubeMount',{videoId:clip.id,playerVars:{playsinline:1,origin:location.origin,rel:0,controls:0,disablekb:1,fs:0,iv_load_policy:3},events:{onReady:()=>{if(version!==clipVersion||clipItems[activeClipIndex]?.id!==clip.id)return;videoReady=true;videoPlayer.mute();videoPlayer.seekTo(Math.max(0,audio.currentTime+videoOffset),true);syncVideo();$('#clipsStatus').textContent='Видео следует за песней. При необходимости поправь сдвиг.'},onError:()=>{if(version!==clipVersion||clipItems[activeClipIndex]?.id!==clip.id)return;if(i+1<clipItems.length){selectClip(i+1);return}$('#videoPlaceholder')?.classList.remove('hidden');$('#clipsStatus').textContent='Встраивание или видео недоступно. Можно открыть клип на YouTube.';videoReady=false}}})}catch(e){if(focusOpen&&version===clipVersion&&clipItems[activeClipIndex]?.id===clip.id){if(i+1<clipItems.length){selectClip(i+1);return}$('#videoPlaceholder')?.classList.remove('hidden');$('#clipsStatus').textContent='YouTube не загрузился. Можно открыть клип отдельно.'}}}
