for(const event of ['timeupdate','play','pause','seeked','loadedmetadata'])audio.addEventListener(event,updateFocusTime);setInterval(()=>{if(focusOpen)updateFocusTime()},700);
document.addEventListener('click',async e=>{const b=e.target.closest('button,[role=button]');if(!b)return;if(['expandPlayer','miniArt'].includes(b.id))openFocus();if(b.id==='closeFocus')closeFocus();if(b.id==='nativeFullscreen'){try{if(window.playerDesktop?.setFullscreen){desktopFullscreen=!desktopFullscreen;await window.playerDesktop.setFullscreen(desktopFullscreen)}else if(document.fullscreenElement)await document.exitFullscreen();else await focusPanel.requestFullscreen()}catch{toast('Системный полный экран недоступен — плеер открыт на всё окно.')}}if(b.dataset.focusControl){$('#'+b.dataset.focusControl).click();updateFocusTime()}if(b.dataset.focusNext)play(find(b.dataset.focusNext));if(b.dataset.focusTab){lyricsManualUntil=0;focusTab=b.dataset.focusTab;$('#focusText').classList.toggle('hidden',focusTab!=='lyrics');$('#focusClips').classList.toggle('hidden',focusTab!=='clips');document.querySelectorAll('[data-focus-tab]').forEach(n=>n.classList.toggle('selected',n===b));if(focusTab==='clips'&&!clipItems.length)loadClips();syncVideo()}if(b.dataset.lyric!==undefined){const t=lyricsLines[+b.dataset.lyric]?.time;if(Number.isFinite(t)){lyricsManualUntil=0;audio.currentTime=Math.max(0,t-lyricsOffset);updateFocusTime();centerLyric(b,true)}}if(b.dataset.clip!==undefined)selectClip(+b.dataset.clip);if(b.id==='retryLyrics')loadLyrics(true);if(b.id==='retryClips')loadClips();if(b.id==='importLrc')$('#lrcFile').click()});
document.addEventListener('input',e=>{if(e.target.id==='focusVolume'){audio.volume=+e.target.value;$('#volume').value=e.target.value;audio.muted=false}if(e.target.id==='focusSeek'&&Number.isFinite(audio.duration))audio.currentTime=audio.duration*Number(e.target.value)/1000;if(e.target.id==='lyricsOffset'){lyricsOffset=Math.max(-60,Math.min(60,Number(e.target.value)||0));updateFocusTime()}if(e.target.id==='videoOffset'){videoOffset=Math.max(-120,Math.min(120,Number(e.target.value)||0));lastVideoCorrection=0;syncVideo()}});
document.addEventListener('change',async e=>{if(e.target.id!=='lrcFile')return;const file=e.target.files[0],trackId=focusTrack;if(!file)return;try{if(file.size>1000000)throw Error();const lines=parseLocalLrc(await file.text());if(!focusOpen||trackId!==focusTrack)return;if(!lines.length)throw Error();lyricsVersion++;lyricsLines=lines;$('#lyricsStatus').textContent='Текст из LRC · синхронизация включена';renderLyrics()}catch{toast('В LRC-файле не найдены строки с временными метками.')}});
