const connectionsBeforeAuth=connectionsScreen;connectionsScreen=function(){let html=connectionsBeforeAuth();if(window.playerDesktop?.isDesktop){html=html.replace('<form id="yandexForm">','<button class="primary automatic-auth" data-signin="yandex">Войти в Яндекс.Музыку</button><p>Войди в открывшемся окне — подключение завершится автоматически.</p><details><summary>Подключить токен вручную</summary><form id="yandexForm">').replace('</form><p id="detail-yandex"','</form></details><p id="detail-yandex"');html=html.replace('<form id="soundcloudForm">','<button class="primary automatic-auth" data-signin="soundcloud">Войти в SoundCloud</button><p>Для личной библиотеки войди в аккаунт. Публичный каталог работает и без входа.</p><details><summary>Настроить Client ID вручную</summary><form id="soundcloudForm">').replace('</form><p id="detail-soundcloud"','</form></details><p id="detail-soundcloud"')}else html+='<p>Автоматический вход Яндекса и SoundCloud доступен в десктопном окне soulroom. Для запуска: start.cmd.</p>';return html};
document.addEventListener('click',async e=>{const b=e.target.closest('[data-signin]');if(!b||!window.playerDesktop)return;b.disabled=true;try{const result=await (b.dataset.signin==='yandex'?window.playerDesktop.signInYandex():window.playerDesktop.signInSoundCloud());toast(result.ok?'Аккаунт подключён.':result.message||'Вход не завершён. Можно попробовать снова.');await refreshConnections()}catch{toast('Не удалось завершить вход. Попробуй снова.')}finally{b.disabled=false}});
