const syncBeforeAmbient=sync;sync=function(){syncBeforeAmbient();if(current)document.documentElement.style.setProperty('--current-art','url("'+(coverSource(current.cover,image(0))).replaceAll('"','%22')+'")')};

document.addEventListener('submit',e=>{if(e.target.id!=='manualClipForm')return;e.preventDefault();try{const u=new URL($('#clipUrl').value.trim());const host=u.hostname.replace(/^www\./,'');if(!['youtube.com','m.youtube.com','youtu.be','youtube-nocookie.com'].includes(host))throw Error();const id=host==='youtu.be'?u.pathname.slice(1).split('/')[0]:u.searchParams.get('v')||u.pathname.match(/^\/(?:embed|shorts)\/([^/]+)/)?.[1];if(!/^[a-zA-Z0-9_-]{11}$/.test(id||''))throw Error();clipVersion++;clipItems=[{id,title:'Клип по твоей ссылке'}];$('#clipChoices').innerHTML='';selectClip(0)}catch{toast('Вставь ссылку на видео YouTube.')}});
